import unittest
from candidate import pluck


class TestPluck(unittest.TestCase):
    def test_normal_case_mixed_values(self):
        self.assertEqual(pluck([4, 2, 3]), [2, 1])

    def test_normal_case_even_in_middle(self):
        self.assertEqual(pluck([1, 2, 3]), [2, 1])

    def test_normal_case_zero_is_smallest_even(self):
        self.assertEqual(pluck([5, 0, 3, 0, 4, 2]), [0, 1])

    def test_empty_array_returns_empty_list(self):
        self.assertEqual(pluck([]), [])

    def test_all_odd_numbers_returns_empty_list(self):
        self.assertEqual(pluck([1, 3, 5, 7, 9]), [])

    def test_single_even_element(self):
        self.assertEqual(pluck([4]), [4, 0])

    def test_single_odd_element_returns_empty(self):
        self.assertEqual(pluck([3]), [])

    def test_single_zero_element(self):
        self.assertEqual(pluck([0]), [0, 0])

    def test_multiple_same_minimum_even_returns_first_index(self):
        self.assertEqual(pluck([6, 4, 4, 2, 2, 8]), [2, 3])

    def test_all_same_even_values(self):
        self.assertEqual(pluck([4, 4, 4, 4]), [4, 0])

    def test_all_same_odd_values(self):
        self.assertEqual(pluck([3, 3, 3, 3]), [])

    def test_even_at_first_position(self):
        self.assertEqual(pluck([2, 4, 6, 8]), [2, 0])

    def test_even_at_last_position(self):
        self.assertEqual(pluck([1, 3, 5, 2]), [2, 3])

    def test_only_even_number_in_array(self):
        self.assertEqual(pluck([1, 3, 5, 8, 7, 9]), [8, 3])

    def test_zero_and_other_evens(self):
        self.assertEqual(pluck([2, 4, 0, 6]), [0, 2])

    def test_large_values(self):
        self.assertEqual(pluck([10000, 5000, 2500]), [2500, 2])

    def test_large_array_with_many_elements(self):
        arr = [i for i in range(1, 10001)]
        self.assertEqual(pluck(arr), [2, 1])

    def test_all_evens_descending_order(self):
        self.assertEqual(pluck([10, 8, 6, 4, 2]), [2, 4])

    def test_all_evens_ascending_order(self):
        self.assertEqual(pluck([2, 4, 6, 8, 10]), [2, 0])

    def test_zero_at_beginning(self):
        self.assertEqual(pluck([0, 2, 4, 6]), [0, 0])

    def test_zero_among_odds(self):
        self.assertEqual(pluck([1, 3, 0, 5, 7]), [0, 2])

    def test_two_zeros_first_wins(self):
        self.assertEqual(pluck([3, 0, 1, 0, 5]), [0, 1])

    def test_even_value_one_is_odd(self):
        self.assertEqual(pluck([1, 1, 1]), [])

    def test_mixed_with_repeated_smallest(self):
        self.assertEqual(pluck([8, 6, 4, 4, 2, 4, 4, 2, 6, 8]), [2, 4])

    def test_returns_list_type(self):
        result = pluck([4, 2, 6])
        self.assertIsInstance(result, list)

    def test_empty_result_is_list(self):
        result = pluck([])
        self.assertIsInstance(result, list)

    def test_result_has_two_elements(self):
        result = pluck([4, 2, 6])
        self.assertEqual(len(result), 2)

    def test_result_elements_are_integers(self):
        result = pluck([4, 2, 6])
        self.assertIsInstance(result[0], int)
        self.assertIsInstance(result[1], int)


if __name__ == '__main__':
    unittest.main()
